#include <iostream>
#include <charconv>
#include <string>
bool parse(const std::string& text, int& result) {
  int candidate = 0;
  const auto [ptr, ec] = std::from_chars(text.data(), text.data() + text.size(), candidate);
  if (ec != std::errc{} || ptr != text.data() + text.size()) return false;
  result = candidate; return true;
}
int main() { int value = 17; std::cout << parse("12x", value) << ' ' << value << '\n'; }

#include <iostream>
#include <charconv>
#include <string>
int main() {
  const std::string text = "999999999999999999999"; int value = 17;
  auto result = std::from_chars(text.data(), text.data() + text.size(), value);
  std::cout << (result.ec == std::errc::result_out_of_range) << ' ' << value << '\n';
}

